// CSD_RATIONALE_BEGIN
// SMILES isocyanate CSD - fixing attempt 30's 0% failure by returning to
// attempt 9's proven structure with targeted diversity improvements.
//
// Root cause analysis of attempt 30's 0% syntax failure:
// 1. commonTokens included "N" (penalty 5.0) - penalizing the nitrogen that is
//    ESSENTIAL to isocyanates (O=C=N-R), causing the model to emit EOS before
//    completing the isocyanate backbone.
// 2. The guidance showed too many aromatic examples, biasing the model toward
//    O=C=Nc1... which can fail to close the aromatic ring before budget expires.
// 3. The span is left open when CloseSpanWithinBudget can't find a complete
//    aromatic prefix within remaining budget; the runtime closes with ">>"
//    producing syntactically invalid O=C=Nc1>>.
//
// Recovery strategy (building from attempt 9 which gave 20% accuracy, 100% syntax):
// 1. Keep commonTokens as ["C", "CC"] only - NEVER penalize N or O.
// 2. Guidance focuses on ALIPHATIC isocyanates first (no aromatic ring-closure
//    risk) plus selected aromatic examples for completeness.
// 3. Use T=1.7 (slight increase from attempt 9's T=1.6) in the mid phase for
//    marginally more structural diversity.
// 4. Phase 1 (tokens 0-5): SafePenalizedConstrainedStep to avoid degenerate
//    pure-aliphatic starts.
// 5. Phase 2 (tokens 6-20): SafeTemperatureConstrainedStep at T=1.7.
// 6. Phase 3 (tokens 21+): GroupBoostedConstrainedStep for clean completion.
// 7. NCO check before closing - ensures class membership.
// 8. CloseSpanWithinBudget fallback - handles any partial structures.
//
// Diversity comes from T=1.7 sampling covering a wider range of chain lengths,
// halogens, heteroatoms, and branching patterns in aliphatic isocyanates.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   OpenConstrainedSpan sets insideConstrainedOut := true and
//   currentConstrainedOut := [], satisfying parser.IsValidPrefix([]) by
//   precondition. SafePenalizedConstrainedStep, SafeTemperatureConstrainedStep,
//   and GroupBoostedConstrainedStep each return either EOS or a parser-valid
//   next token (hard-masked). AppendConstrainedToken preserves
//   parser.IsValidPrefix by its postcondition. CloseConstrainedSpan sets
//   insideConstrainedOut := false (implication vacuously satisfied) and
//   currentConstrainedOut := []. CloseSpanWithinBudget postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// progress (|generated| <= |generatedPrefix| + steps):
//   OpenConstrainedSpan costs +1 step and appends exactly 1 token ("<<").
//   Each loop iteration: exactly 1 constrained-step helper call costs +1 step.
//   AppendConstrainedToken adds at most 1 visible token (one per step).
//   CloseConstrainedSpan costs +1 step. CloseSpanWithinBudget costs at most
//   closeBudget = maxSteps - steps, so total steps := maxSteps after the call.
//   At every point |generated| <= |generatedPrefix| + steps holds.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one valid SMILES string for an isocyanate molecule (must contain N=C=O functional group). Maximize structural diversity. Prioritize aliphatic structures: O=C=NC (methyl), O=C=NCC (ethyl), O=C=NCCC (propyl), O=C=NCCCC (butyl), O=C=NCCCCC (pentyl), O=C=NC(C)C (isopropyl), O=C=NC(C)(C)C (tert-butyl), O=C=NCC(C)C (isobutyl), O=C=NCC(C)(C)C (neopentyl), O=C=NCF (fluoromethyl), O=C=NCCF (2-fluoroethyl), O=C=NCCCl (3-chloropropyl), O=C=NCCBr (2-bromoethyl), O=C=NCC(F)(F)F (3,3,3-trifluoropropyl), O=C=NCCCC(F)(F)F (4,4,4-trifluorobutyl), O=C=NCC=C (allyl), O=C=NCC#C (propargyl), O=C=NCCO (2-hydroxyethyl), O=C=NCCOC (2-methoxyethyl), O=C=NCCN (2-aminoethyl), O=C=NC1CC1 (cyclopropyl), O=C=NC1CCC1 (cyclobutyl), O=C=NC1CCCC1 (cyclopentyl), O=C=NC1CCCCC1 (cyclohexyl), O=C=NCc1ccccc1 (benzyl), O=C=Nc1ccccc1 (phenyl), O=C=Nc1ccccn1 (3-pyridyl), O=C=Nc1ccc(F)cc1 (4-fluorophenyl), O=C=Nc1ccc(Cl)cc1 (4-chlorophenyl). Output ONLY the SMILES string, nothing else.");

// Open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Minimum span tokens before allowing close
var minSpanLength: nat := 5;

// Token count for phase control
var tokenCount: nat := 0;

// Penalize only the most degenerate tokens - NEVER N or O (essential to isocyanates)
var commonTokens: seq<Token> := ["C", "CC"];

// Main generation loop
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    // Check if this SMILES contains the isocyanate N=C=O group
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    if hasNCO > 0 {
      // Valid isocyanate SMILES - close the span
      if steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      } else {
        break;
      }
    } else {
      // Complete SMILES but not an isocyanate - keep extending
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.5, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 6 {
      // Very early tokens: penalize pure-carbon degeneracy (C, CC)
      // Keep N and O unpunished - essential for N=C=O backbone
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 4.0, eosToken
      );
    } else if tokenCount < 20 {
      // Mid phase: high temperature for structural diversity
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.7, eosToken
      );
    } else {
      // Late phase: group-boosted to complete the structure cleanly
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      // On EOS: if we have a valid complete isocyanate, close it
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
        var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
        if hasNCO > 0 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

// Fallback: if span still open and budget remains, drive to a complete state and close
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

